def simulate(n, ants):
    # ants is a list of (x, y, dx, dy)
    # dx, dy are velocities
    t = 0
    max_t = 0
    while ants:
        # find the next meeting or fall off
        min_t = float('inf')
        event = None

        # Fall off events
        for i, (x, y, dx, dy) in enumerate(ants):
            # Time to reach edge
            if dx > 0:
                t_fall = (n - x) / dx
            elif dx < 0:
                t_fall = (x) / abs(dx)
            else:
                t_fall = float('inf')

            if dy > 0:
                t_fall_y = (n - y) / dy
            elif dy < 0:
                t_fall_y = (y) / abs(dy)
            else:
                t_fall_y = float('inf')

            t_fall = min(t_fall, t_fall_y)
            if t_fall < min_t:
                min_t = t_fall
                event = ('fall', i)

        # Meeting events
        for i in range(len(ants)):
            for j in range(i + 1, len(ants)):
                x1, y1, dx1, dy1 = ants[i]
                x2, y2, dx2, dy2 = ants[j]

                # Two ants meet if they are on the same horizontal or vertical line
                # and moving in opposite directions.
                # Case 1: Same y, opposite dx
                if abs(y1 - y2) < 1e-9 and dy1 == 0 and dy2 == 0 and dx1 == -dx2 and dx1 != 0:
                    # They meet if they are moving towards each other
                    if (dx1 > 0 and x1 < x2) or (dx1 < 0 and x1 > x2):
                        t_meet = (x2 - x1) / (dx1 - dx2)
                        if t_meet < min_t:
                            min_t = t_meet
                            event = ('meet', i, j)

                # Case 2: Same x, opposite dy
                if abs(x1 - x2) < 1e-9 and dx1 == 0 and dx2 == 0 and dy1 == -dy2 and dy1 != 0:
                    # They meet if they are moving towards each other
                    if (dy1 > 0 and y1 < y2) or (dy1 < 0 and y1 > y2):
                        t_meet = (y2 - y1) / (dy1 - dy2)
                        if t_meet < min_t:
                            min_t = t_meet
                            event = ('meet', i, j)

        if min_t == float('inf'):
            break

        t += min_t
        max_t = max(max_t, t)

        if event[0] == 'fall':
            ants.pop(event[1])
        elif event[0] == 'meet':
            i, j = event[1], event[2]
            x1, y1, dx1, dy1 = ants[i]
            x2, y2, dx2, dy2 = ants[j]
            # Update positions
